      { context: 'Personajul Nela refuză ajutorul la desen. Spune că dorește să exerseze singură, iar sarcina este sigură. Foaia este crem. Pe masă este un creion verde. Emil alege: întreabă, acceptă răspunsul, lasă desenul Nelei.', question: 'Cum respectă Emil refuzul ajutorului?', facts: [{ text: 'Nela refuză ajutorul la desen.', relevant: true }, { text: 'Spune că dorește să exerseze singură, iar sarcina este sigură.', relevant: true }, { text: 'Foaia este crem.', relevant: false }, { text: 'Pe masă este un creion verde.', relevant: false }], plan: ['Întreabă dacă Nela dorește ajutor la desen.', 'Acceptă refuzul fără insistență.', 'Lasă desenul și creioanele la Nela și verifică faptul că poate continua singură.'], error: { index: 1, wrong: 'Tratează refuzul ca pe o permisiune de a prelua desenul.', alternatives: ['Insistă până când Nela renunță la alegere.', 'Spune că orice refuz al ajutorului trebuie pedepsit.'] }, check: { correct: 'Desenul rămâne al Nelei, iar Emil nu a insistat și nu l-a preluat.', wrong: ['Ajutorul este respectuos chiar dacă încalcă refuzul.', 'Foaia crem anulează alegerea Nelei.'] } },
      { context: 'În poveste, Denis cere să fie luată o cutie aflată pe un raft prea înalt pentru copii. Bibliotecara este disponibilă și poate folosi mijloace potrivite. Cutia are etichetă rotundă. Covorul este albastru. Grupul alege: recunoaște limita, cere adultului, așteaptă în locul sigur.', question: 'Ce indicii arată că ajutorul potrivit este al adultului?', facts: [{ text: 'Cutia cerută de Denis este pe un raft prea înalt pentru copii.', relevant: true }, { text: 'Bibliotecara este disponibilă și poate folosi mijloace potrivite.', relevant: true }, { text: 'Cutia are etichetă rotundă.', relevant: false }, { text: 'Covorul este albastru.', relevant: false }], plan: ['Recunoaște că raftul depășește accesul sigur al copiilor.', 'Cere bibliotecarei să ajute la luarea cutiei.', 'Așteaptă în locul sigur și verifică primirea cutiei cu sprijinul adultului.'], error: { index: 1, wrong: 'Consideră că dorința de a ajuta elimină orice limită de siguranță.', alternatives: ['Refuză sprijinul disponibil doar ca să dovedească putere.', 'Afirmă că eticheta rotundă face raftul accesibil copiilor.'] }, check: { correct: 'Adultul a preluat sarcina inaccesibilă, iar copiii au rămas în siguranță.', wrong: ['Un ajutor bun cere să ignori limitele de siguranță.', 'Covorul albastru face inutil sprijinul adultului.'] } }
