      { context: 'Personajul Tudor observă o bucată de sticlă spartă lângă alee. Adultul însoțitor este aproape. Aleea are o bancă verde. Tudor poartă un rucsac gri. Planul ales: recunoaște obiectul riscant, semnalează de la distanță, verifică preluarea de către adult.', question: 'Ce informații susțin cererea de ajutor fără atingerea sticlei?', facts: [{ text: 'Tudor observă o bucată de sticlă spartă lângă alee.', relevant: true }, { text: 'Adultul însoțitor este aproape.', relevant: true }, { text: 'Aleea are o bancă verde.', relevant: false }, { text: 'Tudor poartă un rucsac gri.', relevant: false }], plan: ['Recunoaște sticla spartă ca obiect care nu se atinge.', 'Anunță adultul și indică locul de la distanță.', 'Verifică dacă adultul a înțeles locul, rămânând departe de sticlă.'], error: { index: 0, wrong: 'Clasifică sticla spartă ca obiect sigur de joacă.', alternatives: ['Spune că orice deșeu poate fi atins de copii.', 'Presupune că sticla nu poate răni fiindcă este lângă alee.'] }, check: { correct: 'Tudor a semnalat locul adultului fără să atingă sticla.', wrong: ['Rucsacul gri garantează protecție la atingerea sticlei.', 'Grija pentru natură obligă copilul să atingă orice deșeu.'] } },
      { context: 'În fotografia studiată de Oana, o rață sălbatică este lângă apă. Regula parcului cere observare de la distanță, fără hrănire. Fotografia are numărul 8. Pe margine este desenat un triunghi. Planul poveștii: citește regula, alege observarea permisă, verifică protejarea animalului.', question: 'Ce alegere respectă rața și regula parcului?', facts: [{ text: 'O rață sălbatică este lângă apă.', relevant: true }, { text: 'Regula parcului cere observare de la distanță, fără hrănire.', relevant: true }, { text: 'Fotografia are numărul 8.', relevant: false }, { text: 'Pe margine este desenat un triunghi.', relevant: false }], plan: ['Citește regula despre distanță și lipsa hrănirii.', 'Alege observarea raței de la distanță, fără să îi ofere hrană.', 'Verifică dacă rața nu a fost apropiată, urmărită sau hrănită.'], error: { index: 2, wrong: 'Declară regula respectată după ce rața a fost hrănită.', alternatives: ['Verifică doar numărul fotografiei, nu comportamentul.', 'Consideră urmărirea raței dovadă de protejare.'] }, check: { correct: 'Observarea păstrează distanța și nu include hrănirea raței.', wrong: ['Un animal sălbatic are nevoie să fie urmărit pentru a fi protejat.', 'Triunghiul permite ignorarea regulii parcului.'] } }
