      { context: 'Personajul Horia tace înaintea prezentării. Nu a spus ce simte și nu dorește să explice acum. Foaia lui este albastră. Sala are un ceas. Colega alege: observă tăcerea, oferă sprijin fără întrebări insistente, verifică respectarea refuzului.', question: 'Ce poți afirma sigur fără să ghicești emoția lui Horia?', facts: [{ text: 'Horia tace înaintea prezentării.', relevant: true }, { text: 'Nu a spus ce simte și nu dorește să explice acum.', relevant: true }, { text: 'Foaia lui este albastră.', relevant: false }, { text: 'Sala are un ceas.', relevant: false }], plan: ['Numește doar observația sigură: Horia tace.', 'Oferă sprijin fără să îi atribui o emoție și fără să ceri explicații insistente.', 'Verifică dacă a fost respectată alegerea lui de a nu explica acum.'], error: { index: 0, wrong: 'Declară sigur că Horia este trist doar fiindcă tace.', alternatives: ['Declară sigur că Horia este furios după culoarea foii.', 'Spune că tăcerea dovedește lipsa oricărei emoții.'] }, check: { correct: 'Raportul distinge tăcerea observată de emoția necunoscută și respectă refuzul.', wrong: ['Tăcerea arată întotdeauna tristețe.', 'Prezența ceasului obligă personajul să explice imediat.'] } },
      { context: 'În poveste, Selena spune: „Sunt furioasă”. Cere o pauză într-un loc sigur, stabilit cu învățătoarea. Caietul are spirală. Scaunul este roșu. Selena alege: numește emoția, cere pauza, verifică pauza fără a răni pe cineva.', question: 'Ce răspuns acceptă emoția și sprijină acțiunea sigură cerută?', facts: [{ text: 'Selena spune: „Sunt furioasă”.', relevant: true }, { text: 'Cere o pauză într-un loc sigur, stabilit cu învățătoarea.', relevant: true }, { text: 'Caietul are spirală.', relevant: false }, { text: 'Scaunul este roșu.', relevant: false }], plan: ['Recunoaște furia declarată de Selena fără învinovățire.', 'Cere pauza în locul sigur stabilit cu învățătoarea.', 'Verifică dacă pauza respectă siguranța și nu este condiționată de dispariția imediată a furiei.'], error: { index: 2, wrong: 'Acceptă pauza numai dacă Selena promite să nu mai simtă niciodată furie.', alternatives: ['Consideră că furia îi dă dreptul să rănească pe cineva.', 'Declară pauza greșită doar fiindcă emoția încă există.'] }, check: { correct: 'Furia nu este condamnată, iar pauza aleasă este sigură și sprijinită de adult.', wrong: ['Orice emoție neplăcută trebuie pedepsită.', 'O spirală pe caiet face permisă orice acțiune.'] } }
